from math import inf
from collections import defaultdict
from functools import lru_cache
import sys
input = sys.stdin.readline
sys.setrecursionlimit(10 ** 6)
t = int(input())

def solve():
	N = int(input())
	A = [int(x) for x in input().split(' ')]
	B = [int(x) for x in input().split(' ')]
	d = defaultdict(list)
	for _ in range(N - 1):
		(x, y) = [int(x) for x in input().split(' ')]
		d[x].append(y)
		d[y].append(x)
	ans = 0

	@lru_cache(None)
	def go(node, parent, c, swapped):
		if len(d[node]) == 1 and node != 1:
			return 1 if swapped and c != B[node - 1] or (not swapped and A[node - 1] != B[node - 1]) else 0
		ans = inf
		if swapped:
			if c != B[node - 1]:
				tans = 1
				for child in d[node]:
					if child != parent:
						tans += go(child, node, B[node - 1], True)
				if tans < ans:
					ans = tans
			else:
				tans = 0
				for child in d[node]:
					if child != parent:
						tans += go(child, node, B[node - 1], True)
				if tans < ans:
					ans = tans
		else:
			if A[node - 1] == B[node - 1]:
				tans = 0
				for child in d[node]:
					if child != parent:
						tans += go(child, node, B[node - 1], False)
				if tans < ans:
					ans = tans
			tans = 1
			for child in d[node]:
				if child != parent:
					tans += go(child, node, B[node - 1], True)
			if tans < ans:
				ans = tans
		return ans
	print(go(1, None, A[0], False))
while t:
	solve()
	t -= 1
